-- SHKB single-tenant navigation and permission baseline.
-- Source: read-only snapshot of the production configuration on 2026-08-14.
-- Scope: tenant label, tenant modules, menu definitions, role definitions and role-menu relations.
-- Deliberately excludes users, user-role assignments, credentials and all business records.

SET NAMES utf8mb4;
START TRANSACTION;

UPDATE `tenant` SET `name` = X'E4B88AE6B5B7E587AFE5A594E888AAE7A9BAE68A80E69CAFE69C89E99990E585ACE58FB8' WHERE `id` = '1000';

-- Production enables the following 12 modules for the single tenant; remove generic modules not used by SHKB.
DELETE FROM `sys_module_tenant` WHERE `tenant_id` = 1000 AND `module_id` IN (7, 12, 15);

-- 67 production-only business menu entries plus 21 SHKB overrides of generic menu entries.
ON DUPLICATE KEY UPDATE
  `code` = VALUES(`code`),
  `name` = VALUES(`name`),
  `title` = VALUES(`title`),
  `icon` = VALUES(`icon`),
  `component_type` = VALUES(`component_type`),
  `component` = VALUES(`component`),
  `request_param` = VALUES(`request_param`),
  `parent_id` = VALUES(`parent_id`),
  `sys_module_id` = VALUES(`sys_module_id`),
  `path` = VALUES(`path`),
  `no_cache` = VALUES(`no_cache`),
  `display` = VALUES(`display`),
  `hidden` = VALUES(`hidden`),
  `permission` = VALUES(`permission`),
  `is_special` = VALUES(`is_special`),
  `available` = VALUES(`available`),
  `description` = VALUES(`description`),
  `update_by` = VALUES(`update_by`),
  `update_by_id` = VALUES(`update_by_id`),
  `update_time` = VALUES(`update_time`);

-- Business role definitions are configuration; user accounts and assignments remain environment-local.
-- Three stale production relations that reference deleted menus are intentionally excluded.
ON DUPLICATE KEY UPDATE
  `code` = VALUES(`code`),
  `name` = VALUES(`name`),
  `permission` = VALUES(`permission`),
  `available` = VALUES(`available`),
  `description` = VALUES(`description`),
  `update_by` = VALUES(`update_by`),
  `update_by_id` = VALUES(`update_by_id`),
  `update_time` = VALUES(`update_time`);

-- Use deterministic IDs for relations missing from the target while preserving existing production relation IDs.
DROP TEMPORARY TABLE IF EXISTS `tmp_v121_role_menu`;
CREATE TEMPORARY TABLE `tmp_v121_role_menu` (
  `role_id` VARCHAR(32) NOT NULL,
  `menu_id` VARCHAR(32) NOT NULL,
  PRIMARY KEY (`role_id`, `menu_id`)
) ENGINE=MEMORY;


SELECT MD5(CONCAT('V1.21:', src.`role_id`, ':', src.`menu_id`)), src.`role_id`, src.`menu_id`
FROM `tmp_v121_role_menu` src
WHERE NOT EXISTS (
  SELECT 1 FROM `sys_role_menu` current_rel
  WHERE BINARY current_rel.`role_id` = BINARY src.`role_id`
    AND BINARY current_rel.`menu_id` = BINARY src.`menu_id`
);

DROP TEMPORARY TABLE `tmp_v121_role_menu`;
COMMIT;
